@Test
public void testPurgeClosedConnections() throws Exception {
    // Ensure that after an Oracle ConnManager releases any connections
    // back into the cache (or closes them as redundant), it does not
    // attempt to re-use the closed connection.
    SqoopOptions options = new SqoopOptions(OracleUtils.CONNECT_STRING, TABLE_NAME);
    OracleUtils.setOracleAuth(options);
    // Create a connection manager, use it, and then recycle its connection
    // into the cache.
    ConnManager m1 = new OracleManager(options);
    Connection c1 = m1.getConnection();
    PreparedStatement s = c1.prepareStatement("SELECT 1 FROM dual", ResultSet.TYPE_FORWARD_ONLY, ResultSet.CONCUR_READ_ONLY);
    ResultSet rs = null;
    try {
        rs = s.executeQuery();
        rs.close();
    } finally {
        s.close();
    }
    ConnManager m2 = new OracleManager(options);
    // get a new connection.
    Connection c2 = m2.getConnection();
    // c1 should now be cached.
    m1.close();
    // Use the second connection to run a statement.
    s = c2.prepareStatement("SELECT 2 FROM dual", ResultSet.TYPE_FORWARD_ONLY, ResultSet.CONCUR_READ_ONLY);
    try {
        rs = s.executeQuery();
        rs.close();
    } finally {
        s.close();
    }
    // c2 should be discarded (c1 is already cached).
    m2.close();
    // Try to get another connection from m2. This should result in
    // a completely different connection getting served back to us.
    Connection c2a = m2.getConnection();
    assertFalse(c1.isClosed());
    assertTrue(c2.isClosed());
    assertFalse(c2a.isClosed());
    s = c2a.prepareStatement("SELECT 3 FROM dual", ResultSet.TYPE_FORWARD_ONLY, ResultSet.CONCUR_READ_ONLY);
    try {
        rs = s.executeQuery();
        rs.close();
    } finally {
        s.close();
    }
    // Close the manager's active connection again.
    m2.close();
}

