@Test
public void testMultiTableImportWithAutoMapperReset() throws IOException {
    String[] argv = getArgv();
    runImport(new ImportAllTablesTool(), argv);
    Path warehousePath = new Path(this.getWarehouseDir());
    FileSystem fs = FileSystem.get(getConf());
    for (int i = 0; i < this.tableNames.size(); ++i) {
        String tableName = this.tableNames.get(i);
        LOG.debug("Validating import of " + tableName);
        Path tablePath = new Path(warehousePath, tableName);
        int numPartFiles = 0;
        List<String> importedData = new ArrayList<String>();
        // We expect utmost 2 files
        for (int m = 0; m < 2; ++m) {
            Path filePath = new Path(tablePath, "part-m-0000" + Integer.toString(m));
            if (fs.exists(filePath)) {
                ++numPartFiles;
                LOG.debug("Reading imported file " + filePath);
                BufferedReader reader = null;
                if (!isOnPhysicalCluster()) {
                    reader = new BufferedReader(new InputStreamReader(new FileInputStream(new File(filePath.toString()))));
                } else {
                    FileSystem dfs = FileSystem.get(getConf());
                    FSDataInputStream dis = dfs.open(filePath);
                    reader = new BufferedReader(new InputStreamReader(dis));
                }
                String line = null;
                try {
                    while ((line = reader.readLine()) != null) {
                        importedData.add(line);
                    }
                } finally {
                    IOUtils.closeStream(reader);
                }
            }
        }
        assertEquals("Table " + tableName + " expected a different number of part files", expectedPartFiles[i], numPartFiles);
        for (int k = 0; k < this.expectedStrings[i].length; ++k) {
            assertEquals("Table " + tableName + "expected a different string", expectedStrings[i][k], importedData.get(k));
        }
    }
}

@Test
public void testSupportedAvroTypes() throws IOException, SQLException {
    GenericData.get().addLogicalTypeConversion(new Conversions.DecimalConversion());
    String[] argv = {};
    final int TOTAL_RECORDS = 1 * 10;
    byte[] b = new byte[] { (byte) 1, (byte) 2 };
    Schema fixed = Schema.createFixed("myfixed", null, null, 2);
